<?php
include 'config.php';$token=$tab_token!==''?$tab_token:$page_token;if(!empty($_SESSION['user_id'])&&$tab_token!==''){header('Location: '.tab_url('dashboard.php'));exit;}$msg='';
if(isset($_POST['login'])){$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=$conn->prepare('SELECT id,name,password FROM users WHERE email=? LIMIT 1');if(!$s)$msg='Database setup error: '.($conn->error?:'Could not prepare login.');else{$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($pass,$u['password'])){$ins=$conn->prepare('INSERT INTO tab_sessions(token,user_id,expires_at) VALUES(?,?,DATE_ADD(NOW(), INTERVAL 12 HOUR)) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),expires_at=VALUES(expires_at)');if($ins){$ins->bind_param('si',$token,$u['id']);if($ins->execute()){$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];header('Location: dashboard.php?tab='.rawurlencode($token));exit;}}$msg='Login session could not be created: '.($conn->error?:'Please try again.');}else$msg='Email or password is incorrect.';}}
?>
